import React, { useState } from 'react';
import { API } from './config';

function UserPanel({ setUserToken, userToken }) {
  const [form, setForm] = useState({});
  const [myChallans, setMyChallans] = useState([]);

  async function signup(e) {
    e.preventDefault();
    try {
      const res = await fetch(API + '/user/signup', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(form)
      });
      const data = await res.json();
      alert(data.message || 'Signup successful');
    } catch (err) {
      console.error(err);
      alert('Signup failed');
    }
  }

  async function login(e) {
    e.preventDefault();
    try {
      const res = await fetch(API + '/user/login', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ email: form.email, password: form.password })
      });
      const data = await res.json();
      if (data.token) {
        setUserToken(data.token);
        localStorage.setItem('uid', data.userId);
        alert('Logged in');
        fetchMine(data.userId);
      } else {
        alert(data.message || 'Error');
      }
    } catch (err) {
      console.error(err);
      alert('Login failed');
    }
  }

  async function fetchMine(userId) {
    const id = userId || localStorage.getItem('uid');
    if (!id) return alert('No user id found');
    try {
      const res = await fetch(API + '/challan/user/' + id);
      const data = await res.json();
      setMyChallans(data);
    } catch (err) {
      console.error(err);
      alert('Failed to fetch challans');
    }
  }

  async function pay(challanId) {
    try {
      const res = await fetch(API + '/challan/pay/' + challanId, { method: 'POST' });
      const data = await res.json();
      alert(data.message || 'Paid');
      fetchMine();
    } catch (err) {
      console.error(err);
      alert('Payment failed');
    }
  }

  return (
    <div>
      <h3>User Panel</h3>
      <div style={{ display: 'flex', gap: 20 }}>
        {/* Signup Form */}
        <form onSubmit={signup}>
          <h4>Signup</h4>
          <input placeholder='name' onChange={e => setForm({ ...form, name: e.target.value })} /><br />
          <input placeholder='email' onChange={e => setForm({ ...form, email: e.target.value })} /><br />
          <input placeholder='vehicleNumber' onChange={e => setForm({ ...form, vehicleNumber: e.target.value })} /><br />
          <input type='password' placeholder='password' onChange={e => setForm({ ...form, password: e.target.value })} /><br />
          <button>Signup</button>
        </form>

        {/* Login Form */}
        <form onSubmit={login}>
          <h4>Login</h4>
          <input placeholder='email' onChange={e => setForm({ ...form, email: e.target.value })} /><br />
          <input type='password' placeholder='password' onChange={e => setForm({ ...form, password: e.target.value })} /><br />
          <button>Login</button>
        </form>
      </div>

      {/* Challans Table */}
      <div>
        <h4>My Challans</h4>
        <button onClick={() => fetchMine()}>Refresh</button>
        <table border='1' cellPadding='6'>
          <thead>
            <tr>
              <th>#</th><th>Vehicle</th><th>Cause</th><th>Fine</th><th>Status</th><th>Action</th>
            </tr>
          </thead>
          <tbody>
            {myChallans.map((c, i) => (
              <tr key={c._id}>
                <td>{i + 1}</td>
                <td>{c.vehicleNumber}</td>
                <td>{c.cause}</td>
                <td>{c.fine}</td>
                <td>{c.status}</td>
                <td>{c.status !== 'Paid' && <button onClick={() => pay(c._id)}>Pay</button>}</td>
              </tr>
            ))}
          </tbody>
        </table>
      </div>
    </div>
  );
}

export default UserPanel;
